(function(root){'use strict';const M=typeof module!=='undefined'?require('./engine.js'):root.MC,N=7,MAX=2048;
const colors=b=>b.map(x=>x.color),copy=b=>b.map(x=>({...x}));
function fresh(rng=Math.random){return M.board(rng).map(color=>({color,value:2}))}
function valid(b){return Array.isArray(b)&&b.length===49&&b.every(x=>x&&Number.isInteger(x.color)&&x.color>=0&&x.color<5&&Number.isInteger(x.value)&&x.value>=2&&x.value<=MAX&&(x.value&(x.value-1))===0)}
function mergePairs(b){const out=[];for(let a=0;a<49;a++)for(const z of [a+N,...(a%N<6?[a+1]:[])])if(z<49&&b[a].color===b[z].color&&b[a].value===b[z].value&&b[a].value<MAX)out.push({a,b:z});return out}
function matchMoves(b){return M.moves(colors(b))}
function refill(b,removed,rng){const gone=new Set(removed),out=copy(b);for(let c=0;c<7;c++){const col=[];for(let r=6;r>=0;r--)if(!gone.has(r*7+c))col.push({...b[r*7+c]});while(col.length<7)col.push({color:Math.floor(rng()*5),value:2});for(let r=6;r>=0;r--)out[r*7+c]=col[6-r]}return out}
function shuffle(b,rng=Math.random){for(let tries=0;tries<300;tries++){const out=copy(b);for(let i=48;i>0;i--){const j=Math.floor(rng()*(i+1));[out[i],out[j]]=[out[j],out[i]]}if(!M.groups(colors(out)).length&&(mergePairs(out).length||matchMoves(out).length))return out}return null}
function settle(b,rng){let out=copy(b),events=[];for(let chain=0;chain<20;chain++){const groups=M.groups(colors(out));if(!groups.length)return {board:out,events};for(const g of groups){const sum=g.cells.reduce((n,i)=>n+out[i].value,0),n=g.cells.length,mult=n>=6?4:n===5?3:n===4?2:1;events.push({color:g.color,cells:g.cells.slice(),damage:sum*mult,charge:Math.min(100,sum*3),chain:chain+1,tier:M.tier(n)})}out=refill(out,groups.flatMap(g=>g.cells),rng)}const clean=shuffle(out,rng);return {board:clean||out,events}}
function act(b,a,z,mode,rng=Math.random){if(!valid(b)||!Number.isInteger(a)||!Number.isInteger(z)||a<0||a>=49||z<0||z>=49||!M.adjacent(a,z))return {ok:false,reason:'adjacent'};const out=copy(b);let merged=0;if(mode==='merge'){if(out[a].color!==out[z].color||out[a].value!==out[z].value)return {ok:false,reason:'equal'};if(out[a].value===MAX)return {ok:false,reason:'max'};merged=out[z].value*2;out[z].value=merged;out[a]={color:Math.floor(rng()*5),value:2};}else if(mode==='match'){[out[a],out[z]]=[out[z],out[a]];if(!M.groups(colors(out)).length)return {ok:false,reason:'line'};}else return {ok:false,reason:'mode'};const result=settle(out,rng);return {ok:true,...result,merged,damage:result.events.reduce((n,e)=>n+e.damage,0)}}
const api={fresh,valid,mergePairs,matchMoves,shuffle,act,MAX};root.MCHybrid=api;if(typeof module!=='undefined')module.exports=api;
})(typeof window!=='undefined'?window:globalThis);
